import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))

    adj = [[] for _ in range(N + 1)]
    for _ in range(N - 1):
        a = int(next(it))
        b = int(next(it))
        adj[a].append(b)
        adj[b].append(a)

    deg = [0] * (N + 1)
    good = [False] * (N + 1)
    for i in range(1, N + 1):
        deg[i] = len(adj[i])
        good[i] = deg[i] >= 4

    if not any(good[1:]):
        print(-1)
        return

    visited = [False] * (N + 1)
    parent = [0] * (N + 1)
    order = []

    for s in range(1, N + 1):
        if not good[s] or visited[s]:
            continue

        visited[s] = True
        stack = [s]

        while stack:
            u = stack.pop()
            order.append(u)

            for v in adj[u]:
                if good[v] and not visited[v]:
                    visited[v] = True
                    parent[v] = u
                    stack.append(v)

    dp = [0] * (N + 1)
    best_core = 0

    for u in reversed(order):
        child_values = []
        for v in adj[u]:
            if good[v] and parent[v] == u:
                child_values.append(dp[v])

        child_values.sort(reverse=True)

        dp[u] = 1 + sum(child_values[:3])
        best_core = max(best_core, 1 + sum(child_values[:4]))

    print(3 * best_core + 2)

if __name__ == "__main__":
